rules = cells('Rules', 'B30:D39')
leaf_costs = dict(zip(values('Leaf costs', 'E30:E32'), values('Leaf costs', 'F30:F32')))

# Build adjacency/multiplicity: parent -> [(component, units)]
graph = {}
for p, c, u in rules:
    graph.setdefault(p, []).append((c, u))

def get_costs(part):
    if part in leaf_costs:
        return {part: leaf_costs[part]}
    cost_map = {}
    for comp, mult in graph.get(part, []):
        sub = get_costs(comp)
        for k, v in sub.items():
            cost_map[k] = cost_map.get(k, 0.0) + v * mult
    return cost_map

crate_costs = get_costs('Crate')
beacon_costs = get_costs('Beacon')

total_crate = sum(crate_costs.values())
total_beacon = sum(beacon_costs.values())
result = round(total_crate - total_beacon, 2)

def get_costs():
    rules_rows = data_rows('Rules', {'B': 'string', 'C': 'string', 'D': 'number'})
    rules = [(cell('Rules', f'B{r}'), cell('Rules', f'C{r}'), num('Rules', f'D{r}')) for r in rules_rows]
    cost_rows = data_rows('Leaf costs', {'E': 'string', 'F': 'number'})
    costs = {cell('Leaf costs', f'E{r}'): num('Leaf costs', f'F{r}') for r in cost_rows}

    children_map = {}
    for p, c, u in rules:
        children_map.setdefault(p, []).append((c, u))

    def cost_of(part):
        if part in costs:
            return costs[part]
        if part not in children_map:
            return 0.0
        return sum(u * cost_of(c) for c, u in children_map[part])

    crate_cost = cost_of('Crate')
    beacon_cost = cost_of('Beacon')
    return round(crate_cost - beacon_cost, 2)

result = get_costs()

